sys_script_include.script:
var BaseManagerUtils = Class.create();
BaseManagerUtils.prototype = {
    initialize: function () { },

    getAvailableManagers: function () {
        var assignedManagers = new Set();

        var grManager = new GlideRecord('x_873666_bases_base_registration');
        grManager.addNotNullQuery('base_manager');
        grManager.query();

        while (grManager.next()) {
            assignedManagers.add(grManager.getValue('base_manager'));
        }

        var allowedManagers = new Set();
        var grRole = new GlideRecord('sys_user_has_role');
        grRole.addQuery('role.name', 'x_873666_bases.Base Manager');
        grRole.query();

        while (grRole.next()) {
            allowedManagers.add(grRole.getValue('user'));
        }

        var queryParts = [];

        if (allowedManagers.size > 0) {
            queryParts.push("sys_idIN" + Array.from(allowedManagers).join(','));
        }

        if (assignedManagers.size > 0) {
            queryParts.push("sys_idNOT IN" + Array.from(assignedManagers).join(','));
        }

        return queryParts.join("^");
    },

    type: 'BaseManagerUtils'
};
